// The compiled, versioned protocol used at runtime. Generated by `npm run protocol:build`.
import protocolJson from '../../protocol/compiled/protocol.json';
import type { Protocol, ProtocolNode } from './schema';

export const protocol = protocolJson as unknown as Protocol;
export const PAEDIATRIC_AGE_BELOW: number = (protocolJson as any).paediatricAgeBelow ?? 18;

export const isReference = (n: ProtocolNode) => !!(n as any).reference;
export const node = (id: string): ProtocolNode => protocol.nodes[id];
/** Short display code, e.g. "K3". Codes repeat across boards; ids are file-qualified. */
export const codeOf = (id: string) => protocol.nodes[id]?.source.code ?? id.split(':')[1] ?? id;
